1	package registry
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"sort"
9		"strings"
10		"sync"
11		"time"
12	)
13	
14	// Registry 是一个已打开的本地登记册。同一目录同时只能被一个 Registry
15	// 独占打开（目录内 flock）；单个 Registry 的方法可被多个 goroutine
16	// 并发调用，所有状态变更与落盘在同一把互斥锁内一次完成。
17	type Registry struct {
18		dir    string
19		store  *store
20		state  *snapshot
21		mu     sync.Mutex
22		closed bool
23		// now 返回当前时间，到期判断以此为准；生产环境为 time.Now，测试可替换。
24		now func() time.Time
25	}
26	
27	// Create 在 dir 新建并打开一个空登记册。调用者通过 dir 指定本机数据
28	// 位置；目录不存在会被创建。目录中已存在登记册数据时返回错误，
29	// 已有的数据不会被覆盖。
30	func Create(dir string) (*Registry, error) {
31		if strings.TrimSpace(dir) == "" {
32			return nil, fmt.Errorf("%w: 数据目录不能为空", ErrInvalidArgument)
33		}
34		if err := os.MkdirAll(dir, dirMode); err != nil {
35			return nil, fmt.Errorf("registry: 无法创建数据目录: %w", err)
36		}
37		if _, err := os.Stat(dataFile(dir)); err == nil {
38			return nil, fmt.Errorf("%w: %s 已存在登记册数据，应用 Open 打开", ErrAlreadyExists, dir)
39		} else if !errors.Is(err, os.ErrNotExist) {
40			return nil, fmt.Errorf("registry: 无法访问数据目录: %w", err)
41		}
42		lock, err := acquireLock(dir)
43		if err != nil {
44			return nil, err
45		}
46		// 取锁后再确认一次，避免与另一个进程的 Create 竞争。
47		if _, err := os.Stat(dataFile(dir)); err == nil {
48			_ = releaseLock(lock)
49			return nil, fmt.Errorf("%w: %s 已存在登记册数据", ErrAlreadyExists, dir)
50		}
51		st := &store{dir: dir, lock: lock}
52		s := newSnapshot()
53		if err := st.save(s); err != nil {
54			_ = releaseLock(lock)
55			return nil, err
56		}
57		return &Registry{dir: dir, store: st, state: s, now: time.Now}, nil
58	}
59	
60	// Open 打开 dir 中的已有登记册。数据文件缺失视为空目录的新建场景，
61	// 应使用 Create；数据存在但无法读取或解析时返回包裹 ErrCorrupt 的
62	// 错误，不会被静默当成空登记册。
63	func Open(dir string) (*Registry, error) {
64		if strings.TrimSpace(dir) == "" {
65			return nil, fmt.Errorf("%w: 数据目录不能为空", ErrInvalidArgument)
66		}
67		if info, err := os.Stat(dir); err != nil {
68			return nil, fmt.Errorf("registry: 无法打开数据目录: %w", err)
69		} else if !info.IsDir() {
70			return nil, fmt.Errorf("%w: %s 不是目录", ErrInvalidArgument, dir)
71		}
72		lock, err := acquireLock(dir)
73		if err != nil {
74			return nil, err
75		}
76		// 数据文件不存在不是"空登记册"：明确报错，提示用 Create 新建，
77		// 绝不把无数据目录静默当成空登记册。
78		if _, err := os.Stat(dataFile(dir)); err != nil {
79			_ = releaseLock(lock)
80			if errors.Is(err, os.ErrNotExist) {
81				return nil, fmt.Errorf("%w: %s 中没有登记册数据，请用 Create 新建", ErrNotFound, dir)
82			}
83			return nil, fmt.Errorf("registry: 无法访问登记册数据: %w", err)
84		}
85		s, err := load(dir)
86		if err != nil {
87			_ = releaseLock(lock)
88			return nil, err
89		}
90		return &Registry{dir: dir, store: &store{dir: dir, lock: lock}, state: s, now: time.Now}, nil
91	}
92	
93	// Close 正常关闭登记册并释放独占锁。关闭后不能再调用其他方法。
94	func (r *Registry) Close() error {
95		r.mu.Lock()
96		defer r.mu.Unlock()
97		if r.closed {
98			return nil
99		}
100		r.closed = true
101		return releaseLock(r.store.lock)
102	}
103	
104	func releaseLock(f *os.File) error {
105		err := f.Close() // Close 同时释放 flock
106		if err != nil {
107			return fmt.Errorf("registry: 关闭登记册失败: %w", err)
108		}
109		return nil
110	}
111	
112	func (r *Registry) checkOpen() error {
113		if r.closed {
114			return fmt.Errorf("registry: 登记册已关闭")
115		}
116		return nil
117	}
118	
119	// commit 将当前状态原子落盘；落盘失败时以磁盘内容为准重新加载，
120	// 避免内存状态与已持久化状态不一致。
121	func (r *Registry) commit() error {
122		if err := r.store.save(r.state); err != nil {
123			if s, lerr := load(r.dir); lerr == nil {
124				r.state = s
125			}
126			return err
127		}
128		return nil
129	}
130	
131	// ---- 账户 ----
132	
133	// RegisterAccount 以唯一编号登记账户，登记后即为可用状态。
134	func (r *Registry) RegisterAccount(id, metadata string) error {
135		r.mu.Lock()
136		defer r.mu.Unlock()
137		if err := r.checkOpen(); err != nil {
138			return err
139		}
140		if strings.TrimSpace(id) == "" {
141			return fmt.Errorf("%w: 账户编号不能为空", ErrInvalidArgument)
142		}
143		if _, ok := r.state.Accounts[id]; ok {
144			return fmt.Errorf("%w: 账户 %s", ErrAlreadyExists, id)
145		}
146		r.state.Accounts[id] = account{ID: id, Metadata: metadata, Active: true}
147		return r.commit()
148	}
149	
150	// DeactivateAccount 停用账户。停用后其原有藏品与历史仍可查询，但不能
151	// 再发行、发起或接收新的转让；停用不影响已经落盘的任何记录。
152	func (r *Registry) DeactivateAccount(id string) error {
153		r.mu.Lock()
154		defer r.mu.Unlock()
155		if err := r.checkOpen(); err != nil {
156			return err
157		}
158		a, ok := r.state.Accounts[id]
159		if !ok {
160			return fmt.Errorf("%w: 账户 %s", ErrNotFound, id)
161		}
162		if !a.Active {
163			return nil // 停用是幂等的终态
164		}
165		a.Active = false
166		r.state.Accounts[id] = a
167		return r.commit()
168	}
169	
170	// GetAccount 查询账户；账户不存在时返回包裹 ErrNotFound 的错误。
171	func (r *Registry) GetAccount(id string) (Account, error) {
172		r.mu.Lock()
173		defer r.mu.Unlock()
174		if err := r.checkOpen(); err != nil {
175			return Account{}, err
176		}
177		a, ok := r.state.Accounts[id]
178		if !ok {
179			return Account{}, fmt.Errorf("%w: 账户 %s", ErrNotFound, id)
180		}
181		return Account{ID: a.ID, Metadata: a.Metadata, Active: a.Active}, nil
182	}
183	
184	// ---- 系列 ----
185	
186	// CreateSeries 登记一个系列，记录创建账户与文字元数据。创建账户必须
187	// 已登记且可用；后续只有该账户能发行该系列的藏品或封存该系列。
188	func (r *Registry) CreateSeries(id, creatorID, metadata string) error {
189		r.mu.Lock()
190		defer r.mu.Unlock()
191		if err := r.checkOpen(); err != nil {
192			return err
193		}
194		if strings.TrimSpace(id) == "" {
195			return fmt.Errorf("%w: 系列编号不能为空", ErrInvalidArgument)
196		}
197		creator, ok := r.state.Accounts[creatorID]
198		if !ok {
199			return fmt.Errorf("%w: 创建账户 %s", ErrNotFound, creatorID)
200		}
201		if !creator.Active {
202			return fmt.Errorf("%w: 创建账户 %s", ErrAccountInactive, creatorID)
203		}
204		if _, ok := r.state.Series[id]; ok {
205			return fmt.Errorf("%w: 系列 %s", ErrAlreadyExists, id)
206		}
207		r.state.Series[id] = series{ID: id, CreatorID: creatorID, Metadata: metadata}
208		return r.commit()
209	}
210	
211	// SealSeries 封存系列。只有系列创建账户可以封存；封存后不能继续发行，
212	// 已发行藏品仍可转让，且封存不能撤销。
213	func (r *Registry) SealSeries(seriesID, operator string) error {
214		r.mu.Lock()
215		defer r.mu.Unlock()
216		if err := r.checkOpen(); err != nil {
217			return err
218		}
219		s, ok := r.state.Series[seriesID]
220		if !ok {
221			return fmt.Errorf("%w: 系列 %s", ErrNotFound, seriesID)
222		}
223		if s.CreatorID != operator {
224			return fmt.Errorf("%w: 只有创建账户 %s 可以封存系列 %s", ErrForbidden, s.CreatorID, seriesID)
225		}
226		if s.Sealed {
227			return nil // 封存不可撤销，重复封存视为已处于封存态
228		}
229		s.Sealed = true
230		r.state.Series[seriesID] = s
231		return r.commit()
232	}
233	
234	// GetSeries 查询系列；不存在时返回包裹 ErrNotFound 的错误。
235	func (r *Registry) GetSeries(id string) (Series, error) {
236		r.mu.Lock()
237		defer r.mu.Unlock()
238		if err := r.checkOpen(); err != nil {
239			return Series{}, err
240		}
241		s, ok := r.state.Series[id]
242		if !ok {
243			return Series{}, fmt.Errorf("%w: 系列 %s", ErrNotFound, id)
244		}
245		return Series{ID: s.ID, CreatorID: s.CreatorID, Metadata: s.Metadata, Sealed: s.Sealed}, nil
246	}
247	
248	// ---- 发行 ----
249	
250	func (req IssueRequest) validatePresent() error {
251		missing := []string{}
252		if strings.TrimSpace(req.Operator) == "" {
253			missing = append(missing, "operator")
254		}
255		if strings.TrimSpace(req.Reason) == "" {
256			missing = append(missing, "reason")
257		}
258		if strings.TrimSpace(req.RequestID) == "" {
259			missing = append(missing, "request_id")
260		}
261		if strings.TrimSpace(req.ItemID) == "" {
262			missing = append(missing, "item_id")
263		}
264		if strings.TrimSpace(req.SeriesID) == "" {
265			missing = append(missing, "series_id")
266		}
267		if strings.TrimSpace(req.BatchNo) == "" {
268			missing = append(missing, "batch_no")
269		}
270		if strings.TrimSpace(req.HolderID) == "" {
271			missing = append(missing, "holder_id")
272		}
273		if len(missing) > 0 {
274			return fmt.Errorf("%w: 发行请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
275		}
276		return nil
277	}
278	
279	func issueParamsSig(req IssueRequest) string {
280		b, _ := json.Marshal(struct {
281			Kind     string `json:"kind"`
282			ItemID   string `json:"item_id"`
283			SeriesID string `json:"series_id"`
284			BatchNo  string `json:"batch_no"`
285			Metadata string `json:"metadata"`
286			HolderID string `json:"holder_id"`
287			Reason   string `json:"reason"`
288		}{"issue", req.ItemID, req.SeriesID, req.BatchNo, req.Metadata, req.HolderID, req.Reason})
289		return string(b)
290	}
291	
292	// Issue 发行一件藏品。成功后持有版本为 1，初始持有人为 req.HolderID。
293	// 操作者必须是系列创建账户且可用，初始持有人必须已登记且可用，系列未
294	// 封存，藏品编号从未使用过。同一 (操作者, 请求号) 且业务参数相同的
295	// 重复提交返回首次结果；参数不同返回 ErrRequestConflict。
296	//
297	// 状态类拒绝的落盘失败时，与整批发行一致：返回保存错误（保留实际写入
298	// 错误）而非该业务错误，结果为空（无藏品编号、无持有人、无版本、无历史
299	// 序号、业务错误为空、不标回放），请求号不被这次未保存的拒绝占用；保存
300	// 条件恢复后用完全相同的请求重提，按当时的业务状态重新判断：拒绝条件仍
301	// 在则重新保存此次拒绝并返回对应业务错误，状态已变为满足请求则正常发行。
302	func (r *Registry) Issue(req IssueRequest) (IssueResult, error) {
303		if err := req.validatePresent(); err != nil {
304			return IssueResult{}, err
305		}
306		r.mu.Lock()
307		defer r.mu.Unlock()
308		if err := r.checkOpen(); err != nil {
309			return IssueResult{}, err
310		}
311	
312		key := requestKey(req.Operator, req.RequestID)
313		sig := issueParamsSig(req)
314		if prev, ok := r.state.Requests[key]; ok {
315			return r.replayIssue(prev, sig)
316		}
317	
318		bizErr := r.checkIssue(req)
319		if bizErr != nil {
320			if !isValidationErr(bizErr) {
321				// 状态类业务拒绝（封存、停用、无权、编号已用等）占用请求号并
322				// 落盘：相同参数重提永远返回这一次拒绝，即使状态后来变化。
323				r.state.Requests[key] = request{
324					Operator: req.Operator, RequestID: req.RequestID, Kind: "issue",
325					Params: sig, Rejected: true, Reason: errCode(bizErr),
326					ItemID: req.ItemID,
327				}
328				if err := r.commit(); err != nil {
329					// 拒绝结果落盘失败：这次拒绝没有被记住，与整批发行一致——
330					// 不能只用业务错误掩盖保存错误，调用者稍后用原请求重提时
331					// 必须按当时状态重新判断，而不是回放一个实际没有保存的
332					// 拒绝。commit 失败时已按磁盘内容重建状态，请求记录随之
333					// 撤销；此处再删一次以覆盖磁盘暂时不可读、状态未能重建
334					// 的情形。整体返回空结果：无藏品编号、无持有人、无版本、
335					// 无历史序号、不标回放、结果中业务错误为空，error 保留
336					// 实际写入错误。
337					delete(r.state.Requests, key)
338					return IssueResult{}, err
339				}
340			}
341			// 校验类错误（引用不存在等）不占用请求号，也不改变任何状态。
342			return IssueResult{ItemID: req.ItemID, Err: bizErr}, bizErr
343		}
344	
345		seq := r.state.NextSeq + 1
346		r.state.NextSeq = seq
347		r.state.Items[req.ItemID] = item{
348			ID: req.ItemID, SeriesID: req.SeriesID, BatchNo: req.BatchNo,
349			Metadata: req.Metadata, IssuedTxID: seq,
350		}
351		r.state.Holdings[req.ItemID] = holding{ItemID: req.ItemID, OwnerID: req.HolderID, Version: 1}
352		r.state.History = append(r.state.History, historyEntry{
353			Seq: seq, Kind: "issue", ItemID: req.ItemID, Operator: req.Operator,
354			Reason: req.Reason, RequestID: req.RequestID,
355			FromID: "", ToID: req.HolderID, FromVersion: 0, ToVersion: 1,
356		})
357		r.state.Requests[key] = request{
358			Operator: req.Operator, RequestID: req.RequestID, Kind: "issue",
359			Params: sig, ItemID: req.ItemID, ToID: req.HolderID, Version: 1, TxSeq: seq,
360		}
361		if err := r.commit(); err != nil {
362			return IssueResult{}, err
363		}
364		return IssueResult{ItemID: req.ItemID, OwnerID: req.HolderID, Version: 1, TxSeq: seq}, nil
365	}
366	
367	// checkIssue 按单件发行的优先级执行与整批共用的发行资格规则：参数合法
368	// 后，操作者的登记/停用问题优先于系列问题，系列问题内部依次为不存在、
369	// 已封存、操作者不是创建账户，藏品编号已占用又优先于初始持有人问题。
370	func (r *Registry) checkIssue(req IssueRequest) error {
371		return r.checkSingleIssueEligibility(req.Operator, req.SeriesID, req.ItemID, req.HolderID)
372	}
373	
374	func (r *Registry) replayIssue(prev request, sig string) (IssueResult, error) {
375		if prev.Kind != "issue" || prev.Params != sig {
376			return IssueResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
377				ErrRequestConflict, prev.Operator, prev.RequestID)
378		}
379		res := IssueResult{ItemID: prev.ItemID, OwnerID: prev.ToID, Version: prev.Version,
380			TxSeq: prev.TxSeq, Replayed: true}
381		if prev.Rejected {
382			res.Err = codeErr(prev.Reason)
383			return res, res.Err
384		}
385		return res, nil
386	}
387	
388	// ---- 转让 ----
389	
390	func (req TransferRequest) validatePresent() error {
391		missing := []string{}
392		if strings.TrimSpace(req.Operator) == "" {
393			missing = append(missing, "operator")
394		}
395		if strings.TrimSpace(req.Reason) == "" {
396			missing = append(missing, "reason")
397		}
398		if strings.TrimSpace(req.RequestID) == "" {
399			missing = append(missing, "request_id")
400		}
401		if strings.TrimSpace(req.ItemID) == "" {
402			missing = append(missing, "item_id")
403		}
404		if strings.TrimSpace(req.ExpectedOwner) == "" {
405			missing = append(missing, "expected_owner")
406		}
407		if strings.TrimSpace(req.ToID) == "" {
408			missing = append(missing, "to_id")
409		}
410		if req.ExpectedVer <= 0 {
411			missing = append(missing, "expected_version")
412		}
413		if len(missing) > 0 {
414			return fmt.Errorf("%w: 转让请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
415		}
416		if req.Price < 0 {
417			return fmt.Errorf("%w: 成交价款 %d 不能为负", ErrInvalidArgument, req.Price)
418		}
419		return nil
420	}
421	
422	func transferParamsSig(req TransferRequest) string {
423		// Price 用 omitempty：价款为 0 时签名与引入价款前的旧格式一致，
424		// 旧登记册中落盘的请求仍可按原参数回放；改价则签名不同、按请求号
425		// 冲突拒绝。
426		b, _ := json.Marshal(struct {
427			Kind          string `json:"kind"`
428			ItemID        string `json:"item_id"`
429			ExpectedOwner string `json:"expected_owner"`
430			ExpectedVer   int64  `json:"expected_version"`
431			ToID          string `json:"to_id"`
432			Price         int64  `json:"price,omitempty"`
433			Reason        string `json:"reason"`
434		}{"transfer", req.ItemID, req.ExpectedOwner, req.ExpectedVer, req.ToID, req.Price, req.Reason})
435		return string(b)
436	}
437	
438	// transferOutcome 是一笔成功转让落盘后的执行结果，供各转让入口组装
439	// 各自的返回结构与请求记录。
440	type transferOutcome struct {
441		seq     int64      // 转让历史序号
442		fromID  string     // 转让前持有人
443		fromVer int64      // 转让前持有版本
444		royalty royaltyRec // 版税应付记录（含价款、明细与余款）
445	}
446	
447	// toVer 是转让后的持有版本。
448	func (o transferOutcome) toVer() int64 { return o.fromVer + 1 }
449	
450	// applyTransfer 完成一笔成功转让的全部状态变化：持有版本加一并换主、
451	// 追加转让历史、按所属系列的版税规则快照计算应付明细与归转让前持有人
452	// 的余款。直接转让、授权代转与整批转让共用这一段逻辑，保证同一笔转让
453	// 的持有、历史与金额记录始终一致；authID 为空表示直接转让。调用方负责
454	// 前置校验、请求结果登记与落盘，调用时必须持有锁且校验已通过。
455	func (r *Registry) applyTransfer(itemID, toID, operator, reason, requestID, authID string, price int64) transferOutcome {
456		h := r.state.Holdings[itemID]
457		seq := r.state.NextSeq + 1
458		r.state.NextSeq = seq
459		from := h.OwnerID
460		fromVer := h.Version
461		h.OwnerID = toID
462		h.Version = fromVer + 1
463		r.state.Holdings[itemID] = h
464		r.state.History = append(r.state.History, historyEntry{
465			Seq: seq, Kind: "transfer", ItemID: itemID, Operator: operator,
466			Reason: reason, RequestID: requestID,
467			FromID: from, ToID: toID, FromVersion: fromVer, ToVersion: fromVer + 1,
468			AuthID: authID,
469		})
470		// 版税按所属系列的规则快照计算；余款归转让前持有人。
471		it := r.state.Items[itemID]
472		royalty := newRoyaltyRec(seq, itemID, it.SeriesID, price,
473			r.state.Series[it.SeriesID].Royalty, from)
474		r.state.Royalties[seq] = royalty
475		return transferOutcome{seq: seq, fromID: from, fromVer: fromVer, royalty: royalty}
476	}
477	
478	// Transfer 由当前持有人发起转让。接收人必须已登记、可用且不同于当前
479	// 持有人；请求必须给出期望持有人与期望版本，藏品不存在或持有人/版本
480	// 不符时返回业务拒绝且不改变任何状态。成交价款（分）由持有人填写，
481	// 非负、未填按 0；成功时按所属系列的版税规则一次落盘各收款账户的
482	// 应付明细与归转让前持有人的余款。同一 (操作者, 请求号) 的相同
483	// 请求重复提交（即使藏品后来已易手）返回首次结果。
484	//
485	// 状态类拒绝的落盘失败时，与整批转让一致：返回保存错误（保留实际写入
486	// 错误）而非该业务错误，结果为空（无藏品编号、无持有变化、无历史序号、
487	// 无金额、业务错误为空、不标回放），请求号不被这次未保存的拒绝占用；
488	// 保存条件恢复后用完全相同的请求重提，按当时的业务状态重新判断：拒绝
489	// 条件仍在则重新保存此次拒绝并返回对应业务错误，状态已变为满足请求则
490	// 正常转出。
491	func (r *Registry) Transfer(req TransferRequest) (TransferResult, error) {
492		if err := req.validatePresent(); err != nil {
493			return TransferResult{}, err
494		}
495		r.mu.Lock()
496		defer r.mu.Unlock()
497		if err := r.checkOpen(); err != nil {
498			return TransferResult{}, err
499		}
500	
501		key := requestKey(req.Operator, req.RequestID)
502		sig := transferParamsSig(req)
503		if prev, ok := r.state.Requests[key]; ok {
504			return r.replayTransfer(prev, sig)
505		}
506	
507		bizErr := r.checkTransfer(req)
508		if bizErr != nil {
509			if !isValidationErr(bizErr) {
510				// 状态类业务拒绝（持有人/版本不符、账户停用、收发同人等）
511				// 占用请求号并落盘，相同参数重提永远返回这一次拒绝。
512				r.state.Requests[key] = request{
513					Operator: req.Operator, RequestID: req.RequestID, Kind: "transfer",
514					Params: sig, Rejected: true, Reason: errCode(bizErr),
515					ItemID: req.ItemID,
516				}
517				if err := r.commit(); err != nil {
518					// 拒绝结果落盘失败：这次拒绝没有被记住，与整批转让一致——
519					// 不能只用业务错误掩盖保存错误，调用者稍后用原请求重提时
520					// 必须按当时状态重新判断，而不是回放一个实际没有保存的
521					// 拒绝。commit 失败时已按磁盘内容重建状态，请求记录随之
522					// 撤销；此处再删一次以覆盖磁盘暂时不可读、状态未能重建
523					// 的情形。整体返回空结果：无藏品编号、无持有变化、无历史
524					// 序号、无金额、不标回放、结果中业务错误为空，error 保留
525					// 实际写入错误。
526					delete(r.state.Requests, key)
527					return TransferResult{}, err
528				}
529			}
530			// 藏品或账户不存在等校验错误不占用请求号，也不改变持有或历史。
531			return TransferResult{ItemID: req.ItemID, Err: bizErr}, bizErr
532		}
533	
534		// 持有变化、历史、版税应付与请求结果在同一临界区内一次落盘。
535		out := r.applyTransfer(req.ItemID, req.ToID, req.Operator, req.Reason, req.RequestID, "", req.Price)
536		r.state.Requests[key] = request{
537			Operator: req.Operator, RequestID: req.RequestID, Kind: "transfer",
538			Params: sig, ItemID: req.ItemID, FromID: out.fromID, ToID: req.ToID,
539			Version: out.toVer(), TxSeq: out.seq,
540		}
541		if err := r.commit(); err != nil {
542			return TransferResult{}, err
543		}
544		return TransferResult{ItemID: req.ItemID, FromID: out.fromID, ToID: req.ToID,
545			Version: out.toVer(), TxSeq: out.seq,
546			Price: out.royalty.Price, Payables: publicPayables(out.royalty.Payees),
547			Remainder: out.royalty.Remainder}, nil
548	}
549	
550	// checkTransfer 按单件转让的优先级执行与整批共用的直接转让资格规则：
551	// 参数合法后，藏品及持有记录不存在优先于账户错误，操作者的登记和停用
552	// 问题优先于接收账户问题，接收账户问题优先于收发同人，收发同人又优先
553	// 于持有信息不符。
554	func (r *Registry) checkTransfer(req TransferRequest) error {
555		return r.checkSingleTransferEligibility(directTransferEligibility{
556			itemID:        req.ItemID,
557			operator:      req.Operator,
558			toID:          req.ToID,
559			expectedOwner: req.ExpectedOwner,
560			expectedVer:   req.ExpectedVer,
561		})
562	}
563	
564	func (r *Registry) replayTransfer(prev request, sig string) (TransferResult, error) {
565		if prev.Kind != "transfer" || prev.Params != sig {
566			return TransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
567				ErrRequestConflict, prev.Operator, prev.RequestID)
568		}
569		res := TransferResult{ItemID: prev.ItemID, FromID: prev.FromID, ToID: prev.ToID,
570			Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
571		if prev.Rejected {
572			res.Err = codeErr(prev.Reason)
573			return res, res.Err
574		}
575		// 回放首次成功的金额：即使藏品后来再次易手或进程重开，仍返回原
576		// 价款与应付明细，不重复计入。
577		res.Price, res.Payables, res.Remainder = r.royaltyOfTx(prev.TxSeq)
578		return res, nil
579	}
580	
581	// ---- 限时一次性代转授权 ----
582	
583	// authzCurrentStatus 计算授权当前状态。撤销与使用是落盘的终态；到期不
584	// 落盘，按当前时间实时判断——从到期时间点起即视为已过期。
585	func authzCurrentStatus(a authzRec, now time.Time) string {
586		switch a.Status {
587		case "revoked":
588			return AuthRevoked
589		case "used":
590			return AuthUsed
591		}
592		if !a.ExpiresAt.IsZero() && !now.Before(a.ExpiresAt) {
593			return AuthExpired
594		}
595		return AuthActive
596	}
