598	func (req CreateAuthorizationRequest) validatePresent() error {
599		missing := []string{}
600		if strings.TrimSpace(req.Operator) == "" {
601			missing = append(missing, "operator")
602		}
603		if strings.TrimSpace(req.Reason) == "" {
604			missing = append(missing, "reason")
605		}
606		if strings.TrimSpace(req.RequestID) == "" {
607			missing = append(missing, "request_id")
608		}
609		if strings.TrimSpace(req.AuthID) == "" {
610			missing = append(missing, "auth_id")
611		}
612		if strings.TrimSpace(req.ItemID) == "" {
613			missing = append(missing, "item_id")
614		}
615		if strings.TrimSpace(req.TrusteeID) == "" {
616			missing = append(missing, "trustee_id")
617		}
618		if strings.TrimSpace(req.ToID) == "" {
619			missing = append(missing, "to_id")
620		}
621		if strings.TrimSpace(req.ExpectedOwner) == "" {
622			missing = append(missing, "expected_owner")
623		}
624		if req.ExpectedVer <= 0 {
625			missing = append(missing, "expected_version")
626		}
627		if req.ExpiresAt.IsZero() {
628			missing = append(missing, "expires_at")
629		}
630		if len(missing) > 0 {
631			return fmt.Errorf("%w: 创建授权请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
632		}
633		if req.Price < 0 {
634			return fmt.Errorf("%w: 成交价款 %d 不能为负", ErrInvalidArgument, req.Price)
635		}
636		return nil
637	}
638	
639	func createAuthzParamsSig(req CreateAuthorizationRequest) string {
640		// Price 用 omitempty：价款为 0 时签名与旧格式一致，旧授权创建请求
641		// 仍可回放；改价则按请求号冲突拒绝。
642		b, _ := json.Marshal(struct {
643			Kind          string `json:"kind"`
644			AuthID        string `json:"auth_id"`
645			ItemID        string `json:"item_id"`
646			TrusteeID     string `json:"trustee_id"`
647			ToID          string `json:"to_id"`
648			ExpectedOwner string `json:"expected_owner"`
649			ExpectedVer   int64  `json:"expected_version"`
650			ExpiresAt     string `json:"expires_at"`
651			Price         int64  `json:"price,omitempty"`
652			Reason        string `json:"reason"`
653		}{"auth_create", req.AuthID, req.ItemID, req.TrusteeID, req.ToID,
654			req.ExpectedOwner, req.ExpectedVer,
655			req.ExpiresAt.UTC().Format(time.RFC3339Nano), req.Price, req.Reason})
656		return string(b)
657	}
658	
659	// CreateAuthorization 由当前持有人为一件已发行藏品创建限时、一次性的
660	// 代转授权：指定唯一授权编号、受托账户、固定接收账户、绝对到期时间，
661	// 以及期望持有人与期望版本。授权绑定创建时的持有版本，不改变持有关系，
662	// 也不限制持有人继续直接转让。受托人不能是授权人；受托人可与接收人
663	// 相同，但接收人也不能是授权人。到期时间必须晚于当前时间。
664	//
665	// 请求号与发行、转让共用同一操作者的请求号范围：相同业务参数重提返回
666	// 首次结果（成功或状态类业务拒绝），参数变化返回 ErrRequestConflict；
667	// 参数错误与引用不存在不占用请求号。
668	func (r *Registry) CreateAuthorization(req CreateAuthorizationRequest) (CreateAuthorizationResult, error) {
669		if err := req.validatePresent(); err != nil {
670			return CreateAuthorizationResult{}, err
671		}
672		r.mu.Lock()
673		defer r.mu.Unlock()
674		if err := r.checkOpen(); err != nil {
675			return CreateAuthorizationResult{}, err
676		}
677	
678		now := r.now()
679		key := requestKey(req.Operator, req.RequestID)
680		sig := createAuthzParamsSig(req)
681		if prev, ok := r.state.Requests[key]; ok {
682			return r.replayCreateAuthz(prev, sig)
683		}
684	
685		if bizErr := r.checkCreateAuthorization(req, now); bizErr != nil {
686			if !isValidationErr(bizErr) {
687				// 状态类业务拒绝（编号占用、停用、同人、版本不符、到期时间
688				// 已过等）占用请求号并落盘；参数错误与引用不存在不占用。
689				r.state.Requests[key] = request{
690					Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_create",
691					Params: sig, Rejected: true, Reason: errCode(bizErr),
692					AuthID: req.AuthID, ItemID: req.ItemID,
693				}
694				_ = r.commit()
695			}
696			return CreateAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
697		}
698	
699		h := r.state.Holdings[req.ItemID]
700		a := authzRec{
701			ID: req.AuthID, ItemID: req.ItemID, GranterID: req.Operator,
702			TrusteeID: req.TrusteeID, ToID: req.ToID, ExpiresAt: req.ExpiresAt,
703			GrantVer: h.Version, Price: req.Price, CreatedAt: now,
704		}
705		r.state.Authzs[req.AuthID] = a
706		authSeq := r.state.NextAuthSeq + 1
707		r.state.NextAuthSeq = authSeq
708		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
709			Seq: authSeq, AuthID: req.AuthID, ItemID: req.ItemID, Kind: "create",
710			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
711			FromStatus: "", ToStatus: AuthActive, OccurredAt: now,
712		})
713		r.state.Requests[key] = request{
714			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_create",
715			Params: sig, AuthID: req.AuthID, ItemID: req.ItemID, Version: h.Version,
716		}
717		if err := r.commit(); err != nil {
718			return CreateAuthorizationResult{}, err
719		}
720		return CreateAuthorizationResult{AuthID: req.AuthID, Status: AuthActive, GrantVer: h.Version}, nil
721	}
722	
723	func (r *Registry) checkCreateAuthorization(req CreateAuthorizationRequest, now time.Time) error {
724		h, ok := r.state.Holdings[req.ItemID]
725		if !ok {
726			if _, itemExists := r.state.Items[req.ItemID]; !itemExists {
727				return fmt.Errorf("%w: 藏品 %s", ErrNotFound, req.ItemID)
728			}
729			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, req.ItemID)
730		}
731		op, ok := r.state.Accounts[req.Operator]
732		if !ok {
733			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, req.Operator)
734		}
735		trustee, ok := r.state.Accounts[req.TrusteeID]
736		if !ok {
737			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.TrusteeID)
738		}
739		to, ok := r.state.Accounts[req.ToID]
740		if !ok {
741			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, req.ToID)
742		}
743		if req.TrusteeID == req.Operator {
744			return fmt.Errorf("%w: 受托人不能是授权人 %s", ErrSameAccount, req.Operator)
745		}
746		if req.ToID == req.Operator {
747			return fmt.Errorf("%w: 接收人不能是授权人 %s", ErrSameAccount, req.Operator)
748		}
749		if !op.Active {
750			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, req.Operator)
751		}
752		if !trustee.Active {
753			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.TrusteeID)
754		}
755		if !to.Active {
756			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, req.ToID)
757		}
758		// 授权编号占用是对象级冲突，优先于当前时间与持有版本检查。
759		if _, exists := r.state.Authzs[req.AuthID]; exists {
760			return fmt.Errorf("%w: 授权编号 %s 已被占用", ErrAlreadyExists, req.AuthID)
761		}
762		// 到期时间不晚于当前时间即为参数错误；从到期时间点起不可使用。
763		if !req.ExpiresAt.After(now) {
764			return fmt.Errorf("%w: 到期时间 %s 必须晚于当前时间",
765				ErrInvalidArgument, req.ExpiresAt.Format(time.RFC3339Nano))
766		}
767		if h.OwnerID != req.ExpectedOwner || h.Version != req.ExpectedVer ||
768			req.Operator != h.OwnerID {
769			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d",
770				ErrConflict, req.ItemID, h.OwnerID, h.Version)
771		}
772		return nil
773	}
774	
775	func (r *Registry) replayCreateAuthz(prev request, sig string) (CreateAuthorizationResult, error) {
776		if prev.Kind != "auth_create" || prev.Params != sig {
777			return CreateAuthorizationResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
778				ErrRequestConflict, prev.Operator, prev.RequestID)
779		}
780		res := CreateAuthorizationResult{AuthID: prev.AuthID, GrantVer: prev.Version,
781			Status: AuthActive, Replayed: true}
782		if prev.Rejected {
783			res.Err = codeErr(prev.Reason)
784			return res, res.Err
785		}
786		return res, nil
787	}
788	
789	func revokeAuthzParamsSig(req RevokeAuthorizationRequest) string {
790		b, _ := json.Marshal(struct {
791			Kind   string `json:"kind"`
792			AuthID string `json:"auth_id"`
793			Reason string `json:"reason"`
794		}{"auth_revoke", req.AuthID, req.Reason})
795		return string(b)
796	}
797	
798	// RevokeAuthorization 撤销一份尚未使用的代转授权。仅授权人可以撤销；
799	// 已使用的授权不能撤销（返回 ErrAuthorizationUsed）。授权已撤销时再次
800	// 撤销不新增授权变更记录，按成功返回。请求号语义与其他操作一致。
801	func (r *Registry) RevokeAuthorization(req RevokeAuthorizationRequest) (RevokeAuthorizationResult, error) {
802		missing := []string{}
803		if strings.TrimSpace(req.Operator) == "" {
804			missing = append(missing, "operator")
805		}
806		if strings.TrimSpace(req.Reason) == "" {
807			missing = append(missing, "reason")
808		}
809		if strings.TrimSpace(req.RequestID) == "" {
810			missing = append(missing, "request_id")
811		}
812		if strings.TrimSpace(req.AuthID) == "" {
813			missing = append(missing, "auth_id")
814		}
815		if len(missing) > 0 {
816			return RevokeAuthorizationResult{}, fmt.Errorf("%w: 撤销授权请求缺少必填字段 %s",
817				ErrInvalidArgument, strings.Join(missing, ", "))
818		}
819		r.mu.Lock()
820		defer r.mu.Unlock()
821		if err := r.checkOpen(); err != nil {
822			return RevokeAuthorizationResult{}, err
823		}
824	
825		now := r.now()
826		key := requestKey(req.Operator, req.RequestID)
827		sig := revokeAuthzParamsSig(req)
828		if prev, ok := r.state.Requests[key]; ok {
829			return r.replayRevokeAuthz(prev, sig)
830		}
831	
832		a, ok := r.state.Authzs[req.AuthID]
833		if !ok {
834			// 引用不存在不占用请求号。
835			err := fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
836			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: err}, err
837		}
838		if a.GranterID != req.Operator {
839			bizErr := fmt.Errorf("%w: 只有授权人 %s 可以撤销授权 %s",
840				ErrForbidden, a.GranterID, req.AuthID)
841			r.recordAuthzRequest(key, sig, req, "auth_revoke", bizErr)
842			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
843		}
844		switch authzCurrentStatus(a, now) {
845		case AuthUsed:
846			bizErr := fmt.Errorf("%w: 授权 %s 已使用，不能撤销", ErrAuthorizationUsed, req.AuthID)
847			r.recordAuthzRequest(key, sig, req, "auth_revoke", bizErr)
848			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
849		case AuthRevoked:
850			// 已撤销是幂等终态：不新增授权变更记录；该请求号仍登记为成功，
851			// 相同请求重放回放同一结果。
852			r.state.Requests[key] = request{
853				Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
854				Params: sig, AuthID: req.AuthID,
855			}
856			if err := r.commit(); err != nil {
857				return RevokeAuthorizationResult{}, err
858			}
859			return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
860		}
861	
862		from := AuthActive
863		if authzCurrentStatus(a, now) == AuthExpired {
864			from = AuthExpired
865		}
866		a.Status = "revoked"
867		a.RevokedAt = now
868		r.state.Authzs[req.AuthID] = a
869		authSeq := r.state.NextAuthSeq + 1
870		r.state.NextAuthSeq = authSeq
871		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
872			Seq: authSeq, AuthID: req.AuthID, ItemID: a.ItemID, Kind: "revoke",
873			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
874			FromStatus: from, ToStatus: AuthRevoked, OccurredAt: now,
875		})
876		r.state.Requests[key] = request{
877			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
878			Params: sig, AuthID: req.AuthID,
879		}
880		if err := r.commit(); err != nil {
881			return RevokeAuthorizationResult{}, err
882		}
883		return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
884	}
885	
886	// recordAuthzRequest 记录授权类操作的状态类业务拒绝并尽力落盘。
887	func (r *Registry) recordAuthzRequest(key, sig string, req RevokeAuthorizationRequest, kind string, bizErr error) {
888		r.state.Requests[key] = request{
889			Operator: req.Operator, RequestID: req.RequestID, Kind: kind,
890			Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
891		}
892		_ = r.commit()
893	}
894	
895	func (r *Registry) replayRevokeAuthz(prev request, sig string) (RevokeAuthorizationResult, error) {
896		if prev.Kind != "auth_revoke" || prev.Params != sig {
897			return RevokeAuthorizationResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
898				ErrRequestConflict, prev.Operator, prev.RequestID)
899		}
900		res := RevokeAuthorizationResult{AuthID: prev.AuthID, Status: AuthRevoked, Replayed: true}
901		if prev.Rejected {
902			res.Err = codeErr(prev.Reason)
903			res.Status = ""
904			return res, res.Err
905		}
906		return res, nil
907	}
908	
909	func proxyTransferParamsSig(req ProxyTransferRequest) string {
910		b, _ := json.Marshal(struct {
911			Kind   string `json:"kind"`
912			AuthID string `json:"auth_id"`
913			Reason string `json:"reason"`
914		}{"proxy_transfer", req.AuthID, req.Reason})
915		return string(b)
916	}
917	
918	// ProxyTransfer 由受托人凭授权发起一次性代转。藏品与接收人均以授权
919	// 记载为准，请求本身不能指定。成功后持有人变为授权中的接收人、持有
920	// 版本加一，授权记为已使用并关联该笔转让；代转同样出现在藏品历史中，
921	// 操作者记为实际受托账户并可通过授权编号追溯。
922	//
923	// 非受托人（ErrForbidden）、授权已撤销（ErrAuthorizationRevoked）、
924	// 已到期（ErrAuthorizationExpired）、已使用（ErrAuthorizationUsed）、
925	// 任一相关账户停用（ErrAccountInactive）以及持有版本已变化
926	// （ErrConflict，即使藏品回到授权人手中也不恢复）分别明确拒绝，拒绝
927	// 不改变持有或授权状态。成功代转用原请求号重放时，即使授权已到期、
928	// 账户已停用或藏品再次易手，仍返回首次的转让结果。
929	func (r *Registry) ProxyTransfer(req ProxyTransferRequest) (ProxyTransferResult, error) {
930		missing := []string{}
931		if strings.TrimSpace(req.Operator) == "" {
932			missing = append(missing, "operator")
933		}
934		if strings.TrimSpace(req.Reason) == "" {
935			missing = append(missing, "reason")
936		}
937		if strings.TrimSpace(req.RequestID) == "" {
938			missing = append(missing, "request_id")
939		}
940		if strings.TrimSpace(req.AuthID) == "" {
941			missing = append(missing, "auth_id")
942		}
943		if len(missing) > 0 {
944			return ProxyTransferResult{}, fmt.Errorf("%w: 代转请求缺少必填字段 %s",
945				ErrInvalidArgument, strings.Join(missing, ", "))
946		}
947		r.mu.Lock()
948		defer r.mu.Unlock()
949		if err := r.checkOpen(); err != nil {
950			return ProxyTransferResult{}, err
951		}
952	
953		now := r.now()
954		key := requestKey(req.Operator, req.RequestID)
955		sig := proxyTransferParamsSig(req)
956		if prev, ok := r.state.Requests[key]; ok {
957			return r.replayProxyTransfer(prev, sig)
958		}
959	
960		if bizErr := r.checkProxyTransfer(req, now); bizErr != nil {
961			if !isValidationErr(bizErr) {
962				r.state.Requests[key] = request{
963					Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
964					Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
965				}
966				_ = r.commit()
967			}
968			return ProxyTransferResult{AuthID: req.AuthID, Err: bizErr}, bizErr
969		}
970	
971		a := r.state.Authzs[req.AuthID]
972		// 代转价款以授权创建时记载为准，执行时不得改价；余款归转让前持有
973		// 人（授权人），不记给受托人。持有变化、历史、应付明细与授权使用
974		// 状态在同一临界区内一次落盘；历史记录实际受托账户并可按授权编号
975		// 追溯。
976		out := r.applyTransfer(a.ItemID, a.ToID, req.Operator, req.Reason, req.RequestID, a.ID, a.Price)
977		a.Status = "used"
978		a.UsedTxSeq = out.seq
979		a.UsedAt = now
980		r.state.Authzs[a.ID] = a
981		authSeq := r.state.NextAuthSeq + 1
982		r.state.NextAuthSeq = authSeq
983		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
984			Seq: authSeq, AuthID: a.ID, ItemID: a.ItemID, Kind: "use",
985			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
986			FromStatus: AuthActive, ToStatus: AuthUsed, TxSeq: out.seq, OccurredAt: now,
987		})
988		r.state.Requests[key] = request{
989			Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
990			Params: sig, AuthID: a.ID, ItemID: a.ItemID, FromID: out.fromID, ToID: a.ToID,
991			Version: out.toVer(), TxSeq: out.seq,
992		}
993		if err := r.commit(); err != nil {
994			return ProxyTransferResult{}, err
995		}
996		return ProxyTransferResult{AuthID: a.ID, ItemID: a.ItemID, FromID: out.fromID,
997			ToID: a.ToID, Version: out.toVer(), TxSeq: out.seq,
998			Price: out.royalty.Price, Payables: publicPayables(out.royalty.Payees),
999			Remainder: out.royalty.Remainder}, nil
1000	}
1001	
1002	func (r *Registry) checkProxyTransfer(req ProxyTransferRequest, now time.Time) error {
1003		a, ok := r.state.Authzs[req.AuthID]
1004		if !ok {
1005			return fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
1006		}
1007		op, ok := r.state.Accounts[req.Operator]
1008		if !ok {
1009			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.Operator)
1010		}
1011		granter, gOk := r.state.Accounts[a.GranterID]
1012		to, tOk := r.state.Accounts[a.ToID]
1013		if req.Operator != a.TrusteeID {
1014			return fmt.Errorf("%w: 账户 %s 不是授权 %s 的受托人",
1015				ErrForbidden, req.Operator, req.AuthID)
1016		}
1017		if !gOk {
1018			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, a.GranterID)
1019		}
1020		if !tOk {
1021			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, a.ToID)
1022		}
1023		if !op.Active {
1024			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.Operator)
1025		}
1026		if !granter.Active {
1027			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, a.GranterID)
1028		}
1029		if !to.Active {
1030			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, a.ToID)
1031		}
1032		switch authzCurrentStatus(a, now) {
1033		case AuthRevoked:
1034			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationRevoked, req.AuthID)
1035		case AuthExpired:
1036			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationExpired, req.AuthID)
1037		case AuthUsed:
1038			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationUsed, req.AuthID)
1039		}
1040		// 授权只在创建时绑定的持有版本上有效；版本单调递增，藏品即使回到
1041		// 授权人手中也不会回到旧版本，旧授权据此永久失效。
1042		h, ok := r.state.Holdings[a.ItemID]
1043		if !ok {
1044			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, a.ItemID)
1045		}
1046		if h.OwnerID != a.GranterID || h.Version != a.GrantVer {
1047			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d，授权绑定 %s 版本 %d",
1048				ErrConflict, a.ItemID, h.OwnerID, h.Version, a.GranterID, a.GrantVer)
1049		}
1050		return nil
1051	}
1052	
1053	func (r *Registry) replayProxyTransfer(prev request, sig string) (ProxyTransferResult, error) {
1054		if prev.Kind != "proxy_transfer" || prev.Params != sig {
1055			return ProxyTransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
1056				ErrRequestConflict, prev.Operator, prev.RequestID)
1057		}
1058		res := ProxyTransferResult{AuthID: prev.AuthID, ItemID: prev.ItemID, FromID: prev.FromID,
1059			ToID: prev.ToID, Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
1060		if prev.Rejected {
1061			res.Err = codeErr(prev.Reason)
1062			return res, res.Err
1063		}
1064		// 回放首次成功的金额：授权到期、账户停用或藏品再次易手后仍返回
1065		// 原价款与应付明细，不重复计入。
1066		res.Price, res.Payables, res.Remainder = r.royaltyOfTx(prev.TxSeq)
1067		return res, nil
1068	}
1069	
1070	// ---- 授权查询 ----
1071	
1072	// GetAuthorization 按编号查询授权内容与撤销、使用状态。授权不存在时
1073	// 返回包裹 ErrNotFound 的错误；返回的 Status 按当前时间实时计算，
1074	// 到期但尚未终结的授权返回 AuthExpired。
1075	func (r *Registry) GetAuthorization(authID string) (Authorization, error) {
1076		r.mu.Lock()
1077		defer r.mu.Unlock()
1078		if err := r.checkOpen(); err != nil {
1079			return Authorization{}, err
1080		}
1081		a, ok := r.state.Authzs[authID]
1082		if !ok {
1083			return Authorization{}, fmt.Errorf("%w: 授权 %s", ErrNotFound, authID)
1084		}
1085		return Authorization{
1086			ID: a.ID, ItemID: a.ItemID, GranterID: a.GranterID, TrusteeID: a.TrusteeID,
1087			ToID: a.ToID, ExpiresAt: a.ExpiresAt, GrantVer: a.GrantVer, Price: a.Price,
1088			Status:    authzCurrentStatus(a, r.now()),
1089			UsedTxSeq: a.UsedTxSeq, UsedAt: a.UsedAt, CreatedAt: a.CreatedAt,
1090			RevokedAt: a.RevokedAt,
1091		}, nil
1092	}
1093	
1094	// AuthorizationHistory 按藏品查看授权变更记录（创建、撤销、使用），
1095	// 按发生先后排列；每条记录包含操作者、原因、请求号与前后状态。藏品
1096	// 不存在时返回包裹 ErrNotFound 的错误。
1097	func (r *Registry) AuthorizationHistory(itemID string) ([]AuthorizationEvent, error) {
1098		r.mu.Lock()
1099		defer r.mu.Unlock()
1100		if err := r.checkOpen(); err != nil {
1101			return nil, err
1102		}
1103		if _, ok := r.state.Items[itemID]; !ok {
1104			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1105		}
1106		out := make([]AuthorizationEvent, 0)
1107		for _, e := range r.state.AuthEvents {
1108			if e.ItemID != itemID {
1109				continue
1110			}
1111			out = append(out, AuthorizationEvent{
1112				Seq: e.Seq, AuthID: e.AuthID, ItemID: e.ItemID, Kind: e.Kind,
1113				Operator: e.Operator, Reason: e.Reason, RequestID: e.RequestID,
1114				FromStatus: e.FromStatus, ToStatus: e.ToStatus, TxSeq: e.TxSeq,
1115				OccurredAt: e.OccurredAt,
1116			})
1117		}
1118		return out, nil
1119	}
1120	
1121	// ---- 查询 ----
1122	
1123	// GetItem 查询单件藏品的静态登记信息；不存在时返回包裹 ErrNotFound 的错误。
1124	func (r *Registry) GetItem(id string) (Item, error) {
1125		r.mu.Lock()
1126		defer r.mu.Unlock()
1127		if err := r.checkOpen(); err != nil {
1128			return Item{}, err
1129		}
1130		it, ok := r.state.Items[id]
1131		if !ok {
1132			return Item{}, fmt.Errorf("%w: 藏品 %s", ErrNotFound, id)
1133		}
1134		return Item{ID: it.ID, SeriesID: it.SeriesID, BatchNo: it.BatchNo,
1135			Metadata: it.Metadata, IssuedTxID: it.IssuedTxID}, nil
1136	}
1137	
1138	// GetHolding 查询藏品当前持有状态；藏品不存在时返回包裹 ErrNotFound 的错误。
1139	func (r *Registry) GetHolding(itemID string) (Holding, error) {
1140		r.mu.Lock()
1141		defer r.mu.Unlock()
1142		if err := r.checkOpen(); err != nil {
1143			return Holding{}, err
1144		}
1145		h, ok := r.state.Holdings[itemID]
1146		if !ok {
1147			return Holding{}, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1148		}
1149		return Holding{ItemID: h.ItemID, OwnerID: h.OwnerID, Version: h.Version}, nil
1150	}
1151	
1152	// HoldingsOf 查询某账户当前持有的全部藏品。账户不存在时返回包裹
1153	// ErrNotFound 的错误；停用账户仍可正常查询。
1154	func (r *Registry) HoldingsOf(accountID string) ([]Holding, error) {
1155		r.mu.Lock()
1156		defer r.mu.Unlock()
1157		if err := r.checkOpen(); err != nil {
1158			return nil, err
1159		}
1160		if _, ok := r.state.Accounts[accountID]; !ok {
1161			return nil, fmt.Errorf("%w: 账户 %s", ErrNotFound, accountID)
1162		}
1163		out := make([]Holding, 0)
1164		for _, h := range r.state.Holdings {
1165			if h.OwnerID == accountID {
1166				out = append(out, Holding{ItemID: h.ItemID, OwnerID: h.OwnerID, Version: h.Version})
1167			}
1168		}
1169		sort.Slice(out, func(i, j int) bool { return out[i].ItemID < out[j].ItemID })
1170		return out, nil
1171	}
1172	
1173	// History 查询藏品的发行与历次成功转让，按发生先后排列。发行记录的
1174	// 前持有人为空、前版本为 0。重复提交不会产生额外历史。藏品不存在时
1175	// 返回包裹 ErrNotFound 的错误。
1176	func (r *Registry) History(itemID string) ([]HistoryEntry, error) {
1177		r.mu.Lock()
1178		defer r.mu.Unlock()
1179		if err := r.checkOpen(); err != nil {
1180			return nil, err
1181		}
1182		if _, ok := r.state.Items[itemID]; !ok {
1183			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1184		}
1185		out := make([]HistoryEntry, 0)
1186		for _, e := range r.state.History {
1187			if e.ItemID != itemID {
1188				continue
1189			}
1190			out = append(out, HistoryEntry{
1191				Seq: e.Seq, Kind: e.Kind, ItemID: e.ItemID, Operator: e.Operator,
1192				Reason: e.Reason, RequestID: e.RequestID, FromID: e.FromID, ToID: e.ToID,
1193				FromVersion: e.FromVersion, ToVersion: e.ToVersion, AuthID: e.AuthID,
1194			})
1195		}
1196		return out, nil
1197	}
1198	
1199	// ---- 幂等辅助 ----
1200	
1201	// requestKey 由完整的操作者账户编号与完整的请求号共同确定一条请求记录。
1202	// 采用 JSON 数组编码而非直接拼接：账户编号或请求号本身允许包含零字符
1203	// （U+0000）等任意字符，直接拼接会让 ("a", "b\x00c") 与 ("a\x00b", "c")
1204	// 之类不同的组合得到相同的键，导致不同账户互相占用请求号、回放别人的
1205	// 结果。JSON 编码对任意字符都无歧义，两个组成部分各自完整参与键的构成。
1206	func requestKey(operator, requestID string) string {
1207		b, _ := json.Marshal([2]string{operator, requestID})
1208		return string(b)
1209	}
1210	
1211	// isValidationErr 判定是否为请求本身不成立的错误：必填缺失，或引用了
1212	// 不存在的账户、系列、藏品。这类请求不占用请求号、不落任何记录，引用
1213	// 对象后来补建后仍可用原请求号完整执行一次；其余拒绝（封存、停用、
1214	// 版本冲突、无权、编号已用、收发同人等状态类业务拒绝）按首次结果记忆
1215	// 并回放。
1216	func isValidationErr(err error) bool {
1217		return errors.Is(err, ErrInvalidArgument) || errors.Is(err, ErrNotFound)
1218	}
1219	
1220	var errCodes = map[error]string{
1221		ErrNotFound:             "not_found",
1222		ErrAlreadyExists:        "already_exists",
1223		ErrAccountInactive:      "account_inactive",
1224		ErrSeriesSealed:         "series_sealed",
1225		ErrConflict:             "conflict",
1226		ErrSameAccount:          "same_account",
1227		ErrForbidden:            "forbidden",
1228		ErrAuthorizationRevoked: "authorization_revoked",
1229		ErrAuthorizationExpired: "authorization_expired",
1230		ErrAuthorizationUsed:    "authorization_used",
1231		ErrRoyaltyFrozen:        "royalty_frozen",
1232		ErrSplitIntentRejected:  "split_intent_rejected",
1233		ErrSplitIntentWithdrawn: "split_intent_withdrawn",
1234		ErrSplitIntentInvalid:   "split_intent_invalid",
1235		ErrSplitIntentExpired:   "split_intent_expired",
1236		ErrSplitAnswered:        "split_answered",
1237	}
1238	
1239	var codeErrs = map[string]error{
1240		"not_found":              ErrNotFound,
1241		"already_exists":         ErrAlreadyExists,
1242		"account_inactive":       ErrAccountInactive,
1243		"series_sealed":          ErrSeriesSealed,
1244		"conflict":               ErrConflict,
1245		"same_account":           ErrSameAccount,
1246		"forbidden":              ErrForbidden,
1247		"authorization_revoked":  ErrAuthorizationRevoked,
1248		"authorization_expired":  ErrAuthorizationExpired,
1249		"authorization_used":     ErrAuthorizationUsed,
1250		"royalty_frozen":         ErrRoyaltyFrozen,
1251		"split_intent_rejected":  ErrSplitIntentRejected,
1252		"split_intent_withdrawn": ErrSplitIntentWithdrawn,
1253		"split_intent_invalid":   ErrSplitIntentInvalid,
1254		"split_intent_expired":   ErrSplitIntentExpired,
1255		"split_answered":         ErrSplitAnswered,
1256	}
1257	
1258	func errCode(err error) string {
1259		for sentinel, code := range errCodes {
1260			if errors.Is(err, sentinel) {
1261				return code
1262			}
1263		}
1264		return "rejected"
1265	}
1266	
1267	func codeErr(code string) error {
1268		if e, ok := codeErrs[code]; ok {
1269			return e
1270		}
1271		return errors.New("registry: 请求曾被拒绝")
1272	}
1273

