359	// TestTransferBatchSaveFailureRetryAfterReopen 覆盖磁盘视角：保存失败后
360	// 原登记册仍可正常读取——关闭后重新 Open，看到的仍是整批前状态；此时用
361	// 原请求号重提同样完整执行一次，而不是回放未保存的成功。
362	func TestTransferBatchSaveFailureRetryAfterReopen(t *testing.T) {
363		dir := tempDir(t)
364		r := mustCreate(t, dir)
365		t.Cleanup(func() { _ = r.Close() })
366		seedBatchSaveFailureWorld(t, r)
367		req := batchSaveFailureReq()
368	
369		blockBatchSave(t, r)
370		res, err := r.TransferBatch(req)
371		assertSaveFailureError(t, err)
372		if len(res.Items) != 0 || res.Replayed {
373			t.Fatalf("保存失败必须整体失败: %+v", res)
374		}
375	
376		// 原数据文件从未被替换：正常关闭并重新打开仍能读取整批前的状态。
377		if err := r.Close(); err != nil {
378			t.Fatal(err)
379		}
380		r2, err := Open(dir)
381		if err != nil {
382			t.Fatalf("失败后原登记册必须仍能正常读取: %v", err)
383		}
384		t.Cleanup(func() { _ = r2.Close() })
385		assertBatchStillPending(t, r2)
386	
387		// 恢复保存条件后，在重开的登记册上用原请求重提：完整执行一次。
388		restoreBatchSave(t, r2)
389		assertBatchRetrySuccess(t, r2, req)
390	}
