394	// assertRejectSaveFailureResult 核对"拒绝结果保存失败"的返回：error 是保存
395	// 错误而非业务拒绝，结果与整批保存失败一致——没有转让条目、没有失败藏品
396	// 编号、不标回放、业务错误为空。
397	func assertRejectSaveFailureResult(t *testing.T, res TransferBatchResult, err error) {
