405	// assertRequestFree 核对请求号未被占用、历史序号未被消耗。
406	func assertRequestFree(t *testing.T, r *Registry, req TransferBatchRequest, wantNextSeq int64) {
407		t.Helper()
408		if _, ok := r.state.Requests[requestKey(req.Operator, req.RequestID)]; ok {
409			t.Fatalf("未保存的拒绝不应占用请求号 %s", req.RequestID)
410		}
411		if r.state.NextSeq != wantNextSeq {
412			t.Fatalf("NextSeq = %d, want %d", r.state.NextSeq, wantNextSeq)
413		}
414	}
