1	package registry
2	
3	import (
4		"errors"
5		"testing"
6	)
7	
8	// 本文件为单件发行补充"拒绝结果保存失败"场景的回归保障：请求内容合法、
9	// 引用对象存在，但因现有状态规则（封存、停用、无权、编号已占用等）不能
10	// 发行，而保存这次拒绝又失败时，必须返回实际的保存错误而非业务拒绝；
11	// 结果整体为空（无藏品编号、无持有人、无版本、无历史序号、业务错误为空、
12	// 不标回放），请求号不被这次未保存的拒绝占用，不登记藏品、不建立持有、
13	// 不追加发行历史、不消耗历史序号，未首次发行的系列也不因此固定版税规则。
14	// 保存条件恢复后用原请求重提按当时状态重新判断与保存，而不是回放未保存
15	// 的拒绝。
16	//
17	// 失败注入复用 blockBatchSave/restoreBatchSave：在临时文件路径上预置目录，
18	// save 在 rename 替换 registry.json 之前确定性失败，原快照完好可读。
19	
20	// assertIssueRejectSaveFailureResult 核对单件发行"拒绝结果保存失败"的
21	// 返回：error 是保存错误而非业务拒绝；结果为空——没有藏品编号、持有人、
22	// 版本、历史序号，不标回放，业务错误为空。
23	func assertSingleIssueRejectSaveFailureResult(t *testing.T, res IssueResult, err error) {
24		t.Helper()
25		assertSaveFailureError(t, err)
26		if res.ItemID != "" || res.OwnerID != "" || res.Version != 0 || res.TxSeq != 0 ||
27			res.Replayed || res.Err != nil {
28			t.Fatalf("拒绝保存失败必须整体失败，结果应为空: %+v", res)
29		}
30	}
31	
32	// assertIssueWorldPristine 核对拒绝保存失败后世界仍是发行前的样子：藏品
33	// 不存在、没有持有与发行历史、历史序号未消耗、请求号未占用。
34	func assertIssueWorldPristine(t *testing.T, r *Registry, itemID, rid string) {
35		t.Helper()
36		if _, err := r.GetItem(itemID); !errors.Is(err, ErrNotFound) {
37			t.Fatalf("失败后 %s 不应被登记: %v", itemID, err)
38		}
39		if _, err := r.GetHolding(itemID); !errors.Is(err, ErrNotFound) {
40			t.Fatalf("失败后 %s 不应有持有: %v", itemID, err)
41		}
42		if _, err := r.History(itemID); !errors.Is(err, ErrNotFound) {
43			t.Fatalf("失败后 %s 不应有历史: %v", itemID, err)
44		}
45		if r.state.NextSeq != 0 {
46			t.Fatalf("NextSeq = %d，失败不应消耗历史序号，仍应为 0", r.state.NextSeq)
47		}
48		if _, ok := r.state.Requests[requestKey("alice", rid)]; ok {
49			t.Fatalf("未保存的拒绝不应占用请求号 %s", rid)
50		}
51	}
52	
53	// TestIssueRejectSaveFailureRetrySameState 覆盖题述核心场景：初始持有人
54	// 停用的拒绝落盘失败时返回保存错误、结果为空、请求号不被占用；保存恢复
55	// 后保持原请求重提，重新判断并重新保存该拒绝（这次不算回放），只有此后
56	// 相同内容再次提交才回放已保存的拒绝。
57	func TestIssueRejectSaveFailureRetrySameState(t *testing.T) {
58		r := mustCreate(t, tempDir(t))
59		setupWorld(t, r)
60		if err := r.DeactivateAccount("bob"); err != nil {
61			t.Fatal(err)
62		}
63		req := issueReq("i1", "bob")
64	
65		// 拒绝条件成立（初始持有人 bob 已停用），但保存这次拒绝失败。
66		blockBatchSave(t, r)
67		res, err := r.Issue(req)
68		assertSingleIssueRejectSaveFailureResult(t, res, err)
69		assertIssueWorldPristine(t, r, req.ItemID, req.RequestID)
70	
71		// 保存条件恢复、拒绝条件仍在：原请求重提重新判断并保存此次拒绝，
72		// 保存成功后才返回业务错误本身；这是一次全新判断，不能标回放。
73		restoreBatchSave(t, r)
74		res, err = r.Issue(req)
75		if !errors.Is(err, ErrAccountInactive) {
76			t.Fatalf("重提应在保存成功后返回业务拒绝 ErrAccountInactive: %v", err)
77		}
78		if res.Replayed || res.ItemID != "i1" || !errors.Is(res.Err, ErrAccountInactive) ||
79			res.OwnerID != "" || res.Version != 0 || res.TxSeq != 0 {
80			t.Fatalf("重提结果异常: %+v", res)
81		}
82		if _, ok := r.state.Requests[requestKey(req.Operator, req.RequestID)]; !ok {
83			t.Fatal("拒绝保存成功后应登记请求结果")
84		}
85	
86		// 拒绝已保存：此后相同内容再次提交才回放该拒绝。
87		res, err = r.Issue(req)
88		if !errors.Is(err, ErrAccountInactive) || !res.Replayed || res.ItemID != "i1" ||
89			!errors.Is(res.Err, ErrAccountInactive) {
90			t.Fatalf("保存后的再次提交应回放已保存的拒绝: %+v, err %v", res, err)
91		}
92	
93		// 系列从未成功发行，被拒（含那次未保存的失败）不固定版税规则，仍可设置。
94		set := SetRoyaltyRequest{
95			Operator: "alice", Reason: "拒绝后设置版税", RequestID: "rr-freeze-check",
96			SeriesID: "s1", Shares: []RoyaltyShare{{AccountID: "alice", Rate: 500}},
97		}
98		if _, err := r.SetRoyalty(set); err != nil {
99			t.Fatalf("未成功发行的系列不应固定版税规则: %v", err)
100		}
101	}
102	
103	// TestIssueRejectSaveFailureRetryAfterFix 覆盖：未保存的拒绝不占用请求
104	// 号——保存恢复后把停用的初始持有人换成已登记且可用的账户，用同一操作者
105	// 和请求号提交，应正常发行，不返回请求号冲突，序号从 1 开始。
106	func TestIssueRejectSaveFailureRetryAfterFix(t *testing.T) {
107		r := mustCreate(t, tempDir(t))
108		setupWorld(t, r)
109		if err := r.RegisterAccount("carol", ""); err != nil {
110			t.Fatal(err)
111		}
112		if err := r.DeactivateAccount("bob"); err != nil {
113			t.Fatal(err)
114		}
115		req := issueReq("i1", "bob")
116	
117		blockBatchSave(t, r)
118		res, err := r.Issue(req)
119		assertSingleIssueRejectSaveFailureResult(t, res, err)
120	
121		// 恢复保存条件，把初始持有人改为可用账户 carol；同一操作者与请求号。
122		restoreBatchSave(t, r)
123		fixed := req
124		fixed.HolderID = "carol"
125		res, err = r.Issue(fixed)
126		if err != nil {
127			t.Fatalf("修正请求后用原请求号重提应正常发行，不能报请求号冲突: %v", err)
128		}
129		if res.Replayed || res.Err != nil || res.ItemID != "i1" || res.OwnerID != "carol" ||
130			res.Version != 1 || res.TxSeq != 1 {
131			t.Fatalf("重提结果异常: %+v", res)
132		}
133		if r.state.NextSeq != 1 {
134			t.Fatalf("NextSeq = %d, want 1", r.state.NextSeq)
135		}
136		h, err := r.GetHolding("i1")
137		if err != nil || h.OwnerID != "carol" || h.Version != 1 {
138			t.Fatalf("i1 持有异常: %+v, err %v", h, err)
139		}
140	
141		// 成功结果保存后，相同内容再提回放首次成功；停用的 bob 不影响回放。
142		replay, err := r.Issue(fixed)
143		if err != nil || !replay.Replayed || replay.OwnerID != "carol" || replay.TxSeq != 1 {
144			t.Fatalf("成功后重提应回放: %+v, err %v", replay, err)
145		}
146	}
147	
148	// TestIssueRejectSaveFailureAfterReopen 覆盖磁盘视角：保存失败后原登记册
149	// 仍可正常读取——关闭重开看到的仍是拒绝前状态，请求号未占用；恢复保存后
150	// 用原请求重提重新保存拒绝。
151	func TestIssueRejectSaveFailureAfterReopen(t *testing.T) {
152		dir := tempDir(t)
153		r := mustCreate(t, dir)
154		setupWorld(t, r)
155		if err := r.SealSeries("s1", "alice"); err != nil {
156			t.Fatal(err)
157		}
158		req := issueReq("i1", "bob")
159	
160		blockBatchSave(t, r)
161		res, err := r.Issue(req)
162		assertSingleIssueRejectSaveFailureResult(t, res, err)
163	
164		if err := r.Close(); err != nil {
165			t.Fatal(err)
166		}
167		r2, err := Open(dir)
168		if err != nil {
169			t.Fatalf("失败后原登记册必须仍能正常读取: %v", err)
170		}
171		t.Cleanup(func() { _ = r2.Close() })
172		if _, err := r2.GetItem("i1"); !errors.Is(err, ErrNotFound) {
173			t.Fatalf("重开后 i1 不应存在: %v", err)
174		}
175		if _, ok := r2.state.Requests[requestKey(req.Operator, req.RequestID)]; ok {
176			t.Fatal("重开后未保存的拒绝不应占用请求号")
177		}
178	
179		restoreBatchSave(t, r2)
180		res, err = r2.Issue(req)
181		if !errors.Is(err, ErrSeriesSealed) || res.Replayed || res.Err == nil {
182			t.Fatalf("重开后重提应重新判断并保存封存拒绝: %+v, err %v", res, err)
183		}
184		// 再次提交才回放。
185		res, err = r2.Issue(req)
186		if !errors.Is(err, ErrSeriesSealed) || !res.Replayed {
187			t.Fatalf("再次提交应回放已保存的拒绝: %+v, err %v", res, err)
188		}
189	}
