191	// TestIssueRejectSaveFailureOperatorError 覆盖操作者层面的拒绝（非创建
192	// 账户）保存失败时结果不附任何发行内容；恢复后重提重新保存并返回原错误。
193	func TestIssueRejectSaveFailureOperatorError(t *testing.T) {
