239		}
240		// 原有藏品与持有记录保持原状。
241		h, err := r.GetHolding("i1")
242		if err != nil || h.OwnerID != "bob" || h.Version != 1 {
243			t.Fatalf("原有持有不应被失败影响: %+v, err %v", h, err)
244		}
245	
246		restoreBatchSave(t, r)
247		res, err = r.Issue(req)
248		if !errors.Is(err, ErrAlreadyExists) {
249			t.Fatalf("重提应返回 ErrAlreadyExists: %v", err)
250		}
251		if res.Replayed || res.ItemID != "i1" || !errors.Is(res.Err, ErrAlreadyExists) {
252			t.Fatalf("重提结果异常: %+v", res)
253		}
254		h, err = r.GetHolding("i1")
255		if err != nil || h.OwnerID != "bob" || h.Version != 1 {
256			t.Fatalf("拒绝后原有持有仍应保持原状: %+v, err %v", h, err)
257		}
258	}
259	
260	// TestIssueValidationErrorIgnoresSaveFailure 覆盖：必填缺失或引用不存在
261	// 属于无需保存的参数/对象错误，即使存储暂时不可写，也仍返回原错误而不是
262	// 保存错误，并且不占用请求号。
263	func TestIssueValidationErrorIgnoresSaveFailure(t *testing.T) {
264		r := mustCreate(t, tempDir(t))
265		setupWorld(t, r)
266	
267		blockBatchSave(t, r)
268		defer restoreBatchSave(t, r)
269	
270		// 必填缺失（缺系列）。
271		missing := issueReq("i1", "bob")
272		missing.SeriesID = ""
273		if _, err := r.Issue(missing); !errors.Is(err, ErrInvalidArgument) {
274			t.Fatalf("必填缺失应返回 ErrInvalidArgument，不能改报保存错误: %v", err)
275		}
276		// 引用对象不存在：未登记的初始持有人。
277		ghost := issueReq("i1", "ghost")
278		res, err := r.Issue(ghost)
279		if !errors.Is(err, ErrNotFound) {
280			t.Fatalf("引用不存在应返回 ErrNotFound，不能改报保存错误: %v", err)
281		}
282		if res.ItemID != "i1" || !errors.Is(res.Err, ErrNotFound) {
283			t.Fatalf("引用不存在的结果异常: %+v", res)
284		}
285		// 操作者未登记。
286		opMissing := issueReq("i1", "bob")
287		opMissing.Operator = "nobody"
288		if _, err := r.Issue(opMissing); !errors.Is(err, ErrNotFound) {
289			t.Fatalf("操作者不存在应返回 ErrNotFound: %v", err)
290		}
291	
292		// 无需保存的错误一律不占用请求号，也不消耗历史序号。
293		for _, rid := range []string{missing.RequestID, ghost.RequestID, opMissing.RequestID} {
294			if _, ok := r.state.Requests[requestKey("alice", rid)]; ok {
295				t.Fatalf("参数/对象错误不应占用请求号 %s", rid)
296			}
297		}
298		if _, ok := r.state.Requests[requestKey("nobody", opMissing.RequestID)]; ok {
299			t.Fatal("参数/对象错误不应占用请求号")
300		}
301		if r.state.NextSeq != 0 {
302			t.Fatalf("NextSeq = %d, want 0", r.state.NextSeq)
303		}
304	}
305	
306	// TestIssueRejectSaveFailureNotCarriedByLaterCommit 覆盖：未保存的拒绝在
307	// 同一已打开登记册上必须彻底撤销——保存条件恢复后另一笔正常操作成功落盘
308	// 时，不能把那次拒绝一起写入。
309	func TestIssueRejectSaveFailureNotCarriedByLaterCommit(t *testing.T) {
