320		}
321	
322		// 保存条件恢复，另一笔完全无关的正常操作成功落盘。
323		restoreBatchSave(t, r)
324		if err := r.RegisterAccount("carol", ""); err != nil {
325			t.Fatalf("其他正常操作应能成功保存: %v", err)
326		}
327	
328		// 成功落盘的快照中不能夹带那次未保存的拒绝。
329		if _, ok := r.state.Requests[requestKey(req.Operator, req.RequestID)]; ok {
330			t.Fatal("后续成功保存不能把未保存的拒绝一起写入")
331		}
332		if _, err := r.GetItem("i1"); !errors.Is(err, ErrNotFound) {
333			t.Fatalf("i1 不应随其他操作被一起写入: %v", err)
334		}
335	
336		// 原请求号此刻仍可自由使用：状态依旧拒绝时重新保存，成功后才占号。
337		res, err := r.Issue(req)
338		if !errors.Is(err, ErrAccountInactive) || res.Replayed {
339			t.Fatalf("原请求号应仍可使用并重新判断: %+v, err %v", res, err)
340		}
